(function(global){
"use strict";
const originalPdf=global.MilosPDF;
const mediaApi=global.MilosMedia;
if(!originalPdf||typeof originalPdf.observationPdf!=="function"||!mediaApi)return;
const encoder=new TextEncoder();
let crcTable=null;
function table(){if(crcTable)return crcTable;crcTable=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1);crcTable[n]=c>>>0}return crcTable}
function crc32(bytes){const t=table();let c=0xffffffff;for(let i=0;i<bytes.length;i++)c=t[(c^bytes[i])&255]^(c>>>8);return (c^0xffffffff)>>>0}
function safeName(value,fallback){const x=String(value||fallback||"file").replace(/[\\/:*?"<>|\u0000-\u001f]+/g,"-").replace(/\s+/g," ").trim().slice(0,120);return x||fallback||"file"}
function uniqueName(name,used){let clean=safeName(name,"media"),candidate=clean,n=2;const dot=clean.lastIndexOf("."),base=dot>0?clean.slice(0,dot):clean,ext=dot>0?clean.slice(dot):"";while(used.has(candidate.toLowerCase()))candidate=`${base}-${n++}${ext}`;used.add(candidate.toLowerCase());return candidate}
function dosStamp(ms){const d=new Date(Number(ms)||Date.now()),year=Math.max(1980,d.getFullYear());return{time:((d.getHours()&31)<<11)|((d.getMinutes()&63)<<5)|((Math.floor(d.getSeconds()/2))&31),date:(((year-1980)&127)<<9)|(((d.getMonth()+1)&15)<<5)|(d.getDate()&31)}}
function u16(view,offset,value){view.setUint16(offset,value,true)}
function u32(view,offset,value){view.setUint32(offset,value>>>0,true)}
async function makeZip(entries){const parts=[],central=[];let offset=0;for(const entry of entries){const blob=entry.blob instanceof Blob?entry.blob:new Blob([entry.blob||""]),size=blob.size;if(size>0xffffffff)throw new Error("A media file is too large for this ZIP export.");const bytes=new Uint8Array(await blob.arrayBuffer()),crc=crc32(bytes),nameBytes=encoder.encode(entry.name),stamp=dosStamp(entry.modifiedAt),local=new Uint8Array(30+nameBytes.length),lv=new DataView(local.buffer);u32(lv,0,0x04034b50);u16(lv,4,20);u16(lv,6,0x0800);u16(lv,8,0);u16(lv,10,stamp.time);u16(lv,12,stamp.date);u32(lv,14,crc);u32(lv,18,size);u32(lv,22,size);u16(lv,26,nameBytes.length);u16(lv,28,0);local.set(nameBytes,30);parts.push(local,blob);const cd=new Uint8Array(46+nameBytes.length),cv=new DataView(cd.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,8,0x0800);u16(cv,10,0);u16(cv,12,stamp.time);u16(cv,14,stamp.date);u32(cv,16,crc);u32(cv,20,size);u32(cv,24,size);u16(cv,28,nameBytes.length);u16(cv,30,0);u16(cv,32,0);u16(cv,34,0);u16(cv,36,0);u32(cv,38,0);u32(cv,42,offset);cd.set(nameBytes,46);central.push(cd);offset+=local.byteLength+size}
const centralSize=central.reduce((n,x)=>n+x.byteLength,0),end=new Uint8Array(22),ev=new DataView(end.buffer);u32(ev,0,0x06054b50);u16(ev,4,0);u16(ev,6,0);u16(ev,8,entries.length);u16(ev,10,entries.length);u32(ev,12,centralSize);u32(ev,16,offset);u16(ev,20,0);return new Blob([...parts,...central,end],{type:"application/zip"})}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1800)}
async function captureObservationPdf(args){const JsPDF=global.jspdf&&global.jspdf.jsPDF;if(typeof JsPDF!=="function")throw new Error("The offline PDF builder is unavailable.");let captured=null;function CaptureJsPDF(){const doc=Reflect.construct(JsPDF,Array.from(arguments));doc.save=function(name){captured={name:safeName(name,"Milos-Observation.pdf"),blob:doc.output("blob")};return doc};return doc}CaptureJsPDF.prototype=JsPDF.prototype;try{CaptureJsPDF.API=JsPDF.API}catch(_){};global.jspdf.jsPDF=CaptureJsPDF;let returned="";try{returned=await originalPdf.observationPdf.apply(originalPdf,args)}finally{global.jspdf.jsPDF=JsPDF}if(!captured||!(captured.blob instanceof Blob))throw new Error("Milos could not prepare the observation PDF for export.");if(returned&&!captured.name)captured.name=safeName(returned,"Milos-Observation.pdf");return captured}
async function sourceMedia(observation){const items=Array.isArray(observation&&observation.media)?observation.media:[],out=[];for(const item of items){const type=String(item&&item.type||"").toLowerCase();if(!type.startsWith("video/")&&!type.startsWith("audio/"))continue;try{const stored=await mediaApi.getFile(item.id);if(stored&&stored.blob)out.push({name:stored.name||item.name||"observation-media",blob:stored.blob,modifiedAt:stored.createdAt||item.createdAt||Date.now(),type:String(stored.type||type)})}catch(_){}}
return out}
async function observationPdf(observation,profile,course,qrPayload){const captured=await captureObservationPdf([observation,profile,course,qrPayload]),media=await sourceMedia(observation);if(!media.length){download(captured.blob,captured.name);return captured.name}const used=new Set(),entries=[{name:uniqueName(captured.name,used),blob:captured.blob,modifiedAt:Date.now()}];media.forEach((item,index)=>entries.push({name:uniqueName(item.name||`Observation-media-${index+1}`,used),blob:item.blob,modifiedAt:item.modifiedAt}));const zip=await makeZip(entries),base=captured.name.replace(/\.pdf$/i,"")||"Milos-Observation",zipName=`${safeName(base,"Milos-Observation")}-with-media.zip`;download(zip,zipName);return zipName}
function patchAudioCapture(scope=document){const roots=[];if(scope&&scope.nodeType===1&&scope.matches&&scope.matches(".milos-media-actions"))roots.push(scope);if(scope&&scope.querySelectorAll)roots.push(...scope.querySelectorAll(".milos-media-actions"));roots.forEach(actions=>{if(actions.querySelector("[data-milos-record-audio]"))return;const label=document.createElement("label");label.className="milos-secondary milos-file-button";label.setAttribute("data-milos-record-audio","1");label.innerHTML='Record audio<input type="file" accept="audio/*" capture data-observation-media>';actions.appendChild(label)})}
function startAudioPatch(){const root=document.getElementById("milosApp")||document.body;patchAudioCapture(root);new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>patchAudioCapture(node)))).observe(root,{childList:true,subtree:true})}
global.MilosPDF=Object.freeze(Object.assign({},originalPdf,{observationPdf}));
global.MilosObservationBundle=Object.freeze({version:"2.2",makeZip,sourceMedia});
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",startAudioPatch,{once:true});else startAudioPatch();
})(window);
